from calliopemini import *
import neopixel

n = 3
np = neopixel.NeoPixel(pin_RGB,n)

def bounce(cycles, delay):
    for i in range(n * cycles):
        for j in range(n):
            np[j] = (0, 0, 128)
        if (i // n) % 2 == 0:
            np[i % n] = (0, 0, 0)
        else:
            np[n - 1 - (i % n)] = (0, 0, 0)
        np.show()
        sleep(delay)

bounce(10, 200)

from calliopemini import *
import neopixel

n = 3
np = neopixel.NeoPixel(pin_RGB,n)

def fade(cycles, delay):
    for i in range(0, cycles * 256, 8):
        for j in range(n):
            if (i // 256) % 2 == 0:
                val = i & 0xff
            else:
                val = 255 - (i & 0xff)
            np[j] = (val, 0, 0)
        np.show()
        sleep(delay)

fade(10, 50)

from calliopemini import *
import neopixel

n = 3
np = neopixel.NeoPixel(pin_RGB, n)

def wheel(pos):
    # Input a value 0 to 255 to get a color value.
    # The colours are a transition r - g - b - back to r.
    if pos < 0 or pos > 255:
        return (0, 0, 0)
    if pos < 85:
        return (255 - pos * 3, pos * 3, 0)
    if pos < 170:
        pos -= 85
        return (0, 255 - pos * 3, pos * 3)
    pos -= 170
    return (pos * 3, 0, 255 - pos * 3)

def rainbow(wait):
    for j in range(255):
        for i in range(n):
            pixel_index = (i * 256 // n) + j
            np[i] = wheel(pixel_index & 255)
        np.show()

while True:
    rainbow(1) # call the function rainbow in the while loop

